import sqlite3
import os
import hashlib
import hmac
import secrets
from http.server import HTTPServer, BaseHTTPRequestHandler
import json
import urllib.parse
import re
from datetime import datetime, timedelta

DB_PATH = '/tmp/analytics_app.db'
SECRET_KEY = os.environ.get('APP_SECRET', secrets.token_hex(32))
SESSION_MAX_AGE = timedelta(hours=24)

def get_db():
    conn = sqlite3.connect(DB_PATH)
    conn.execute('PRAGMA journal_mode=WAL')
    return conn

def init_db():
    conn = get_db()
    conn.executescript('''
        CREATE TABLE IF NOT EXISTS users (
            id INTEGER PRIMARY KEY AUTOINCREMENT,
            username TEXT UNIQUE NOT NULL,
            password_hash TEXT NOT NULL,
            display_name TEXT NOT NULL,
            role TEXT DEFAULT 'user',
            created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP
        );
        CREATE TABLE IF NOT EXISTS user_events (
            id INTEGER PRIMARY KEY AUTOINCREMENT,
            user_id INTEGER NOT NULL,
            event_type TEXT NOT NULL,
            event_source TEXT NOT NULL,
            metadata TEXT,
            created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,
            FOREIGN KEY (user_id) REFERENCES users(id)
        );
        CREATE TABLE IF NOT EXISTS analytics_reports (
            id INTEGER PRIMARY KEY AUTOINCREMENT,
            report_name TEXT NOT NULL,
            query_filter TEXT NOT NULL,
            generated_by INTEGER,
            created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP
        );
    ''')
    conn.commit()
    conn.close()

def hash_password(password):
    salt = secrets.token_hex(16)
    h = hashlib.pbkdf2_hmac('sha256', password.encode(), salt.encode(), 100000)
    return f"{salt}:{h.hex()}"

def verify_password(password, password_hash):
    salt, h = password_hash.split(':')
    computed = hashlib.pbkdf2_hmac('sha256', password.encode(), salt.encode(), 100000)
    return hmac.compare_digest(computed.hex(), h)

def create_session_token(user_id):
    payload = f"{user_id}:{datetime.utcnow().isoformat()}:{secrets.token_hex(8)}"
    sig = hmac.new(SECRET_KEY.encode(), payload.encode(), hashlib.sha256).hexdigest()
    return f"{payload}:{sig}"

def validate_session(token):
    try:
        parts = token.rsplit(':', 1)
        if len(parts) != 2:
            return None
        payload, sig = parts
        expected = hmac.new(SECRET_KEY.encode(), payload.encode(), hashlib.sha256).hexdigest()
        if not hmac.compare_digest(sig, expected):
            return None
        payload_parts = payload.split(':')
        user_id = int(payload_parts[0])
        # Enforce session expiration based on the embedded issue timestamp.
        issued_at_str = payload_parts[1]
        issued_at = datetime.fromisoformat(issued_at_str)
        if datetime.utcnow() - issued_at > SESSION_MAX_AGE:
            return None
        return user_id
    except Exception:
        return None

# === DATA ACCESS LAYER ===

class UserRepository:
    @staticmethod
    def create_user(username, password, display_name):
        """Safely creates user with parameterized query"""
        conn = get_db()
        pw_hash = hash_password(password)
        try:
            conn.execute(
                'INSERT INTO users (username, password_hash, display_name) VALUES (?, ?, ?)',
                (username, pw_hash, display_name)
            )
            conn.commit()
            return True
        except sqlite3.IntegrityError:
            return False
        finally:
            conn.close()

    @staticmethod
    def get_user_by_username(username):
        conn = get_db()
        cur = conn.execute('SELECT * FROM users WHERE username = ?', (username,))
        row = cur.fetchone()
        conn.close()
        if row:
            return {'id': row[0], 'username': row[1], 'password_hash': row[2],
                    'display_name': row[3], 'role': row[4]}
        return None

    @staticmethod
    def get_user_by_id(user_id):
        conn = get_db()
        cur = conn.execute('SELECT * FROM users WHERE id = ?', (user_id,))
        row = cur.fetchone()
        conn.close()
        if row:
            return {'id': row[0], 'username': row[1], 'password_hash': row[2],
                    'display_name': row[3], 'role': row[4]}
        return None

class EventRepository:
    @staticmethod
    def log_event(user_id, event_type, event_source, metadata=None):
        """Safely logs event with parameterized query"""
        conn = get_db()
        conn.execute(
            'INSERT INTO user_events (user_id, event_type, event_source, metadata) VALUES (?, ?, ?, ?)',
            (user_id, event_type, event_source, json.dumps(metadata) if metadata else None)
        )
        conn.commit()
        conn.close()

    @staticmethod
    def get_events_for_user(user_id):
        conn = get_db()
        cur = conn.execute(
            'SELECT * FROM user_events WHERE user_id = ? ORDER BY created_at DESC LIMIT 50',
            (user_id,)
        )
        rows = cur.fetchall()
        conn.close()
        return [{'id': r[0], 'user_id': r[1], 'event_type': r[2],
                 'event_source': r[3], 'metadata': r[4]} for r in rows]

# === ANALYTICS ENGINE ===

class QueryBuilder:
    """Builds analytical queries from stored report configurations.
    All queries use parameterized values to prevent injection."""

    @staticmethod
    def _sanitize_identifier(name):
        """Allow only alphanumeric and underscore for identifiers"""
        if re.match(r'^[a-zA-Z_][a-zA-Z0-9_]*$', name):
            return name
        raise ValueError(f"Invalid identifier: {name}")

    @staticmethod
    def build_event_summary(filter_expression, group_by_field='event_type', use_literal=False):
        """Build summary query for analytics dashboard.

        Args:
            filter_expression: WHERE clause filter value
            group_by_field: field to group results by
            use_literal: if True, embed filter directly (for pre-validated stored filters)
                        if False, use as parameter (for user-supplied runtime filters)
        """
        try:
            safe_group = QueryBuilder._sanitize_identifier(group_by_field)
        except ValueError:
            safe_group = 'event_type'

        if use_literal:
            # For internally-stored, pre-validated filter expressions
            query = f"SELECT {safe_group}, COUNT(*) as cnt FROM user_events WHERE {filter_expression} GROUP BY {safe_group} ORDER BY cnt DESC"
            return query, []
        else:
            query = f"SELECT {safe_group}, COUNT(*) as cnt FROM user_events WHERE event_source = ? GROUP BY {safe_group} ORDER BY cnt DESC"
            return query, [filter_expression]

class AnalyticsEngine:
    @staticmethod
    def generate_report_from_config(report_id):
        """Generate analytics from a stored report configuration.
        Report configs are created by admin users and stored in DB."""
        conn = get_db()
        cur = conn.execute('SELECT * FROM analytics_reports WHERE id = ?', (report_id,))
        row = cur.fetchone()
        conn.close()
        if not row:
            return None

        report_name = row[1]
        query_filter = row[2]  # Retrieved from database - assumed trusted internal data

        conn = get_db()
        query, params = QueryBuilder.build_event_summary(query_filter)
        cur = conn.execute(query, params)
        results = cur.fetchall()
        conn.close()

        return {
            'report_name': report_name,
            'results': [{'group': r[0], 'count': r[1]} for r in results]
        }

    @staticmethod
    def generate_user_activity_report(user_id, source_filter):
        """Generate per-user activity report with user-specified source filter."""
        conn = get_db()
        # Use parameterized query for user activity
        user = UserRepository.get_user_by_id(user_id)
        if not user:
            return None

        # Safely parameterized query - no string interpolation of user data
        query = "SELECT event_type, COUNT(*) as cnt FROM user_events WHERE user_id = ? AND event_source = ? GROUP BY event_type ORDER BY cnt DESC"
        cur = conn.execute(query, (user_id, user['display_name']))
        results = cur.fetchall()
        conn.close()

        return {
            'user': user['display_name'],
            'results': [{'group': r[0], 'count': r[1]} for r in results]
        }

# === HTTP HANDLER ===

class AppHandler(BaseHTTPRequestHandler):
    def _send_json(self, data, status=200):
        self.send_response(status)
        self.send_header('Content-Type', 'application/json')
        self.send_header('X-Content-Type-Options', 'nosniff')
        self.end_headers()
        self.wfile.write(json.dumps(data).encode())

    def _read_body(self):
        length = int(self.headers.get('Content-Length', 0))
        if length > 10240:  # 10KB limit
            return None
        return self.rfile.read(length)

    def _get_current_user(self):
        cookie = self.headers.get('Cookie', '')
        for part in cookie.split(';'):
            part = part.strip()
            if part.startswith('session='):
                token = part[8:]
                return validate_session(token)
        return None

    def do_POST(self):
        path = urllib.parse.urlparse(self.path).path

        if path == '/api/register':
            self._handle_register()
        elif path == '/api/login':
            self._handle_login()
        elif path == '/api/events/log':
            self._handle_log_event()
        elif path == '/api/reports/create':
            self._handle_create_report()
        else:
            self._send_json({'error': 'not found'}, 404)

    def do_GET(self):
        path = urllib.parse.urlparse(self.path).path
        params = urllib.parse.parse_qs(urllib.parse.urlparse(self.path).query)

        if path == '/api/reports/generate':
            self._handle_generate_report(params)
        elif path == '/api/activity':
            self._handle_activity_report(params)
        else:
            self._send_json({'error': 'not found'}, 404)

    def _handle_register(self):
        body = self._read_body()
        if not body:
            self._send_json({'error': 'invalid request'}, 400)
            return
        try:
            data = json.loads(body)
        except json.JSONDecodeError:
            self._send_json({'error': 'invalid json'}, 400)
            return

        username = str(data.get('username', ''))[:64]
        password = str(data.get('password', ''))
        display_name = str(data.get('display_name', ''))[:128]

        if len(username) < 3 or len(password) < 8:
            self._send_json({'error': 'validation failed'}, 400)
            return

        if not re.match(r'^[a-zA-Z0-9_]+$', username):
            self._send_json({'error': 'invalid username format'}, 400)
            return

        # display_name allows special characters for international names
        if UserRepository.create_user(username, password, display_name):
            self._send_json({'status': 'created'}, 201)
        else:
            self._send_json({'error': 'username taken'}, 409)

    def _handle_login(self):
        body = self._read_body()
        if not body:
            self._send_json({'error': 'invalid request'}, 400)
            return
        try:
            data = json.loads(body)
        except json.JSONDecodeError:
            self._send_json({'error': 'invalid json'}, 400)
            return

        username = str(data.get('username', ''))
        password = str(data.get('password', ''))

        user = UserRepository.get_user_by_username(username)
        if user and verify_password(password, user['password_hash']):
            token = create_session_token(user['id'])
            self.send_response(200)
            self.send_header('Content-Type', 'application/json')
            self.send_header('Set-Cookie', f'session={token}; HttpOnly; SameSite=Strict; Path=/')
            self.end_headers()
            self.wfile.write(json.dumps({'status': 'ok'}).encode())
            EventRepository.log_event(user['id'], 'login', 'auth_system')
        else:
            self._send_json({'error': 'invalid credentials'}, 401)

    def _handle_log_event(self):
        user_id = self._get_current_user()
        if not user_id:
            self._send_json({'error': 'unauthorized'}, 401)
            return

        body = self._read_body()
        if not body:
            self._send_json({'error': 'invalid request'}, 400)
            return
        try:
            data = json.loads(body)
        except json.JSONDecodeError:
            self._send_json({'error': 'invalid json'}, 400)
            return

        event_type = str(data.get('event_type', ''))[:64]
        event_source = str(data.get('event_source', ''))[:128]
        metadata = data.get('metadata')

        if not event_type or not event_source:
            self._send_json({'error': 'missing fields'}, 400)
            return

        EventRepository.log_event(user_id, event_type, event_source, metadata)
        self._send_json({'status': 'logged'})

    def _handle_create_report(self):
        user_id = self._get_current_user()
        if not user_id:
            self._send_json({'error': 'unauthorized'}, 401)
            return

        user = UserRepository.get_user_by_id(user_id)
        if not user or user['role'] != 'admin':
            self._send_json({'error': 'forbidden'}, 403)
            return

        body = self._read_body()
        if not body:
            self._send_json({'error': 'invalid request'}, 400)
            return
        try:
            data = json.loads(body)
        except json.JSONDecodeError:
            self._send_json({'error': 'invalid json'}, 400)
            return

        report_name = str(data.get('name', ''))[:128]
        query_filter = str(data.get('filter', ''))[:512]

        if not report_name or not query_filter:
            self._send_json({'error': 'missing fields'}, 400)
            return

        conn = get_db()
        conn.execute(
            'INSERT INTO analytics_reports (report_name, query_filter, generated_by) VALUES (?, ?, ?)',
            (report_name, query_filter, user_id)
        )
        conn.commit()
        conn.close()
        self._send_json({'status': 'created'}, 201)

    def _handle_generate_report(self, params):
        user_id = self._get_current_user()
        if not user_id:
            self._send_json({'error': 'unauthorized'}, 401)
            return

        report_id = params.get('id', [None])[0]
        if not report_id:
            self._send_json({'error': 'missing report id'}, 400)
            return

        try:
            report_id = int(report_id)
        except ValueError:
            self._send_json({'error': 'invalid id'}, 400)
            return

        result = AnalyticsEngine.generate_report_from_config(report_id)
        if result:
            self._send_json(result)
        else:
            self._send_json({'error': 'report not found'}, 404)

    def _handle_activity_report(self, params):
        user_id = self._get_current_user()
        if not user_id:
            self._send_json({'error': 'unauthorized'}, 401)
            return

        source = params.get('source', ['all'])[0]
        result = AnalyticsEngine.generate_user_activity_report(user_id, source)
        if result:
            self._send_json(result)
        else:
            self._send_json({'error': 'user not found'}, 404)

    def log_message(self, format, *args):
        pass  # Suppress default logging

if __name__ == '__main__':
    init_db()
    server = HTTPServer(('127.0.0.1', 8080), AppHandler)
    server.serve_forever()
